<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Provider; use App\Models\Service; use App\Services\SlotService; use App\Support\ApiPresenter; use Carbon\CarbonImmutable; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class PublicProviderController extends Controller { public function index(): JsonResponse { $providers=Provider::with(['user','services'=>fn($q)=>$q->where('services.is_active',true)->wherePivot('is_active',true)])->where('is_active',true)->paginate(15);return response()->json(['data'=>$providers->getCollection()->map(fn($p)=>ApiPresenter::provider($p))->values(),'meta'=>['current_page'=>$providers->currentPage(),'last_page'=>$providers->lastPage(),'per_page'=>$providers->perPage(),'total'=>$providers->total()]]);} public function show(Provider $provider): JsonResponse {abort_unless($provider->is_active,404);$provider->load(['user','services'=>fn($q)=>$q->where('services.is_active',true)->wherePivot('is_active',true)]);return response()->json(['data'=>ApiPresenter::provider($provider)]);} public function slots(Request $request,Provider $provider,SlotService $slots): JsonResponse {$validated=$request->validate(['date'=>['required','date_format:Y-m-d'],'service_id'=>['required','integer','exists:services,id']]);$localDate=CarbonImmutable::parse($validated['date'],$provider->timezone)->startOfDay();if($localDate->lt(CarbonImmutable::now($provider->timezone)->startOfDay())){return response()->json(['message'=>'Date cannot be in the past.'],422);}$service=Service::findOrFail($validated['service_id']);return response()->json(['data'=>$slots->availableSlots($provider,$service,$validated['date'])]);} }
